window.DICTIONARY_ENTRY_SHARDS["006c-0079"]={"006c-0079:ef375f8a6856fe":{"word":"Lymphdrainage","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Lymph·drai·na·ge","de-DE":"Lymph·drai·na·ge"},"forms":[{"form":"Lymphdränage","tags":["alternative"]},{"form":"Lymphdrainage","tags":["Nominativ","Singular"]},{"form":"Lymphdrainagen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"verkürzt für „physiologische Lymphdrainage“, physiologischer Abtransport überschüssiger Flüssigkeit aus Körpergewebe über die Lymphgefäße"},{"definition":"verkürzt für „manuelle Lymphdrainage“, eine spezielle physiotherapeutische Behandlung, wobei durch sanfte oberflächliche Manipulation des Bindegewebes die Lymphflüssigkeit verschoben und der Lymphabfluss (Lymphsystem) aktiviert wird"}],"synonyms":["Massage"],"origins":[],"examples":[{"text":"„Im Hinblick auf eine reduzierte physiologische Lymphdrainage der Membrana fibrosa, liegt es nahe, nach einer Unterstützung der manuellen Lymphdrainage zu suchen, […]“","reference":"Günther Bringezu, Otto Schreiner: Lehrbuch der Entstauungstherapie: Grundlagen, Beschreibung und Bewertung der Verfahren, Behandlungskonzepte für die Praxis, 2014, Springer Verlag, ISBN 3642549225, Seite 217"},{"text":"„Es existiert keine direkte Lymphdrainage der Haut in die Lnn. submandibulares, da diese Lymphknotengruppe unterhalb des Platysma lokalisiert ist. […] Die physiologische Lymphdrainage des Nasenrachens verläuft zunächst in dorsolateraler, dann in dorsolateralkaudaler Richtung. […]“","reference":"Jochen A. Werner: Lymphknotenerkrankungen im Kopf-Hals-Bereich: Onkologie und Differenzialdiagnostik, 2013, Springer Verlag, ISBN 3642559239, Seite 16 f."},{"text":"Nach der Lymphdrainage tun die Beine nicht mehr weh.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Lymphdrainage","id":"ef375f8a6856fe"},"006c-0079:42c12902ed0d2f":{"word":"Lymphsystem","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Lymph·sys·tem","de-DE":"Lymph·sys·tem"},"forms":[{"form":"Lymphsystem","tags":["Nominativ","Singular"]},{"form":"Lymphsysteme","tags":["Nominativ","Plural"]},{"form":"Lymphsystems","tags":["Genitiv","Singular"]},{"form":"Lymphsystemen","tags":["Dativ","Plural"]}],"senses":[{"definition":"Gefäßsystem, das überschüssige Flüssigkeit aus dem Gewebe abtransportiert sowie dem Blutkreislauf wieder zuführt und Teile dessen (Lymphatische Organe, Lymphknoten) zum Immunsystem der Wirbeltiere gegen Krankheitserreger, Fremdpartikel und krankhaft veränderte Körperbestandteile (zum Beispiel Tumorzellen) gehören"}],"synonyms":["lymphatisches System"],"origins":["Determinativkompositum aus den Substantiven Lymphe und System sowie der Subtraktionsfuge -e"],"examples":[{"text":"„Im Lymphsystem werden pro Tag etwa 2 Liter Lymphflüssigkeit transportiert.“","reference":"Wikipedia-Artikel „Lymphatisches System“"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Lymphsystem","id":"42c12902ed0d2f"},"006c-0079:e4fa5be2a6f0e6":{"word":"Lyrik","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ly·rik","de-DE":"Ly·rik"},"forms":[{"form":"Lyrik","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Kunstform der Literatur (Gedicht)"},{"definition":"gedichtetes Werk eines Künstlers"}],"synonyms":["Dichtung","Gedichte","liedhafte Dichtung","Poesie"],"origins":["Im 19. Jahrhundert von französisch lyrique ^(→ fr) (aus der Wortverbindung poésie lyrique ^(→ fr)) entlehnt, dem lateinisch lyricus ^(→ la) „zum Spiel der Leier gehörig“ und zuvor altgriechisch λυρικός (lyrikos^☆) ^(→ grc) zugrunde liegt, dem Adjektiv zu λύρα (lyra^☆) ^(→ grc) „Leier“."],"examples":[{"text":"Die Lyrik wurde und wird immer wieder auch von der populären Musikkultur beeinflusst.","reference":""},{"text":"„Das große Zeitgefühl hatte uns ergriffen, ob wir uns nun für die ersten Aeroplanflieger oder für die neue Lyrik begeisterten, wir hatten eine Tür aufgestoßen, wir waren unterwegs, wir konnten nicht mehr zurück.“","reference":"Carl Zuckmayer: Als wär's ein Stück von mir. Horen der Freundschaft. S. Fischer, (Frankfurt/Main) 1994, ISBN 3-10-396502-8, Seite 204."},{"text":"„Derlei spekulative Erwägungen sind Reiner Wild fremd. In seiner umfangreichen Studie über \"Goethes klassische Lyrik\" geht es ihm vielmehr um den linearen Nachweis, daß diese Lyrik \"Teil und Ausdruck des 'Projekts Klassik'\" sei, mit dem \"Goethe und Schiller in gemeinsamer Arbeit auf tiefgreifende Krisenerfahrungen am Ende des 18. Jahrhunderts\" antworteten.“","reference":"Geret Luhr: Gewalt des Gleichmasses – Reiner Wild beschreibt Goethes klassische Lyrik als vorbildliches Projekt. Orthographisch korrigiert."}],"idioms":[],"collocations":[],"derivations":["Lyriker","lyrisch","Lyrikband"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Lyrik","id":"e4fa5be2a6f0e6"},"006c-0079:02cc459f3ccdf2":{"word":"Lysosom","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Lys·o·som","de-DE":"Lys·o·som"},"forms":[{"form":"Lysosom","tags":["Nominativ","Singular"]},{"form":"Lysosoms","tags":["Genitiv","Singular"]},{"form":"Lysosomen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Zellorganelle mit Membran, die Enzyme enthält, die der Verdauung dienen"}],"synonyms":["Abbaukörperchen"],"origins":["von altgriechisch λύσις (lysis^☆) ^(→ grc) „Lösung“ und σῶμα (sōma^☆) ^(→ grc) „Körper, Leib“"],"examples":[{"text":"„Als lysosomale Speicherkrankheiten werden vererbte Stoffwechselerkrankungen bezeichnet, bei denen Fehlfunktionen im Lysosom (Zellorganelle) vorliegen.“","reference":"und Bianka Wiebner: Das Leber-Buch. Schlütersche, 2021, ISBN 978-3-8426-3044-4, Seite 81 (Zitiert nach Google Books)"},{"text":"„Dafür besitzen nahezu alle Zellen in deinem Körper ein eingebautes Abfallentsorgungssystem, genannt Lysosom.“","reference":"Dave Asprey: Super Human. Riva Verlag, 2020, ISBN 978-3-7453-0893-8, Seite 70 (Zitiert nach Google Books)"},{"text":"„Die neu entstandenen (nativen) Lysosomen haben Durchmesser von 25–200 nm und werden als primäre Lysosomen bezeichnet.“","reference":"Thomas Wenisch: Kurzlehrbuch Biologie. Elsevier Health Sciences, 2018, ISBN 978-3-437-09615-0, Seite 22 (Zitiert nach Google Books)"},{"text":"„Endosomen und Lysosomen sind membranbegrenzte Zellorganellen mit unterschiedlich sauren pH-Werten, die alle dem Abbau organischer Strukturen dienen.“","reference":"Universität des Saarlandes: Taschenbuch Histologie. 2017, ISBN 978-3-437-18002-6, Seite 18 (Zitiert nach Google Books)"},{"text":"„Der nicht abgebaute Abfall sammelt sich im Lysosom, welches anschwillt und immer mehr Raum in der Zelle einnimmt, was den Transport von anderen Materialien im Hauptteil der Zelle behindert.“","reference":"Aubrey de Grey, Michael Rae: Niemals alt!. transcript Verlag, 2015, ISBN 978-3-8394-1336-4, Seite 110 (Zitiert nach Google Books)"},{"text":"„Cholesterinester und Triglyzeride werden über Lipoproteinrezeptoren von Zellen aufgenommen und gelangen durch Endozytose in die Lysosomen.“","reference":"Stephan vom Dahl, Frank Lammert, Kurt Ullrich, Udo Wendel: Angeborene Stoffwechselkrankheiten bei Erwachsenen. Springer-Verlag, 2015, ISBN 978-3-642-45188-1, Seite 364 (Zitiert nach Google Books)"}],"idioms":[],"collocations":[],"derivations":["lysosomal"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Lysosom","id":"02cc459f3ccdf2"},"006c-0079:c767deed086461":{"word":"Lysergsäurediethylamid","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Lys·erg·säu·re·di·ethyl·amid","de-DE":"Lys·erg·säu·re·di·ethyl·amid"},"forms":[{"form":"LSD","tags":["Kurzform"]},{"form":"Lysergsäurediethylamid","tags":["Nominativ","Singular"]},{"form":"Lysergsäurediäthylamid","tags":["variant"]},{"form":"Lysergsäurediethylamids","tags":["Genitiv","Singular"]}],"senses":[{"definition":"halluzinogene Droge (Alkaloid aus dem Mutterkorn, heute synthetisch hergestellt)"}],"synonyms":["Acid","LSD","Lysergic Acid Diethylamide","Pappe"],"origins":[],"examples":[{"text":"Lysergsäurediethylamid ist ein Derivat der Lysergsäure, dem Grundkörper der Mutterkornalkaloide, welche in der Natur vorkommen.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Lysergsäurediethylamid","id":"c767deed086461"},"006c-0079:6bd71fffe5fef5":{"word":"Lydia","partOfSpeech":"Vorname","gender":"die","hyphenation":{"de-CH":"Ly·dia","de-DE":"Ly·dia"},"forms":[{"form":"Lydia","tags":["Nominativ","Singular"]},{"form":"Lydias","tags":["Nominativ","Plural"]}],"senses":[{"definition":"weiblicher Vorname"}],"synonyms":[],"origins":["nach einer Person aus dem Neuen Testament, der Name bedeutet „die aus Lydien (→Wikipedia, in Kleinasien) Stammende“"],"examples":[{"text":"Lydia hat die Verantwortung übernommen.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lydia","id":"6bd71fffe5fef5"},"006c-0079:983e0d98789693":{"word":"Lymphknoten","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Lymph·kno·ten","de-DE":"Lymph·kno·ten"},"forms":[{"form":"Lymphknoten","tags":["Nominativ","Singular"]},{"form":"Lymphknotens","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Teil des Lymphsystems, verdickte Stelle von 5-10mm der Lymphgefäße, wo Filtrierung der Lymphflüssigkeit stattfindet"}],"synonyms":["Lymphdrüse"],"origins":["Determinativkompositum aus dem Stamm von Lymphe und dem Substantiv Knoten"],"examples":[{"text":"Die Lymphknoten sind etwas angeschwollen.","reference":""},{"text":"„Im Frühjahr dieses Jahres erkrankte Ethel an Zungenkrebs, der bereits auf den Rachen und die Lymphknoten übergegriffen hatte.“","reference":"Blake Bailey: Philip Roth. Biografie. Hanser, München 2023 (übersetzt von Dirk van Gunsteren, Thomas Gunkel), ISBN 978-3-446-27612-3, Seite 88. Englisch 2021 erschienen."}],"idioms":[],"collocations":[],"derivations":["Lymphknotenbiopsie","Lymphknotenentzündung","Lymphknotenkrebs","Lymphknotenmetastase","Lymphknotenschwellung"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Lymphknoten","id":"983e0d98789693"},"006c-0079:a179d95e799788":{"word":"Lyzeum","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Ly·ze·um","de-DE":"Ly·ze·um"},"forms":[{"form":"Lyzeen","tags":["Nominativ","Plural"]},{"form":"Lyzeum","tags":["Nominativ","Singular"]},{"form":"Lyzeums","tags":["Genitiv","Singular"]}],"senses":[{"definition":"ein von den Humanisten den Universitäten verliehenes Adelsprädikat"},{"definition":"im 19. Jahrhundert eine Bezeichnung für Gymnasium in Deutschland (vergleiche die französische Bezeichnung lycée)"},{"definition":"eine höhere Mädchenschule"},{"definition":"Fachhochschule für katholische Theologie"}],"synonyms":["Mädchengymnasium"],"origins":["das Wort wurde von den Humanisten im 16. Jahrhundert von dem lateinischen Substantiv lyceum / Lyceum als Lyzeum in die deutsche Sprache übernommen.","Das Lyzeum war ursprünglich das dem Gott Apollon Lykeios („der Wolfstöter“) geweihte Heiligtum Lykeion vor den Toren des antiken Athens. In direkter Nachbarschaft hierzu unterhielt der altgriechische Philosoph Aristoteles seine Lehranstalt, die somit auch als Lyzeum bezeichnet wurde."],"examples":[{"text":"„Auch in der höhern Unterrichtsanstalt zu Düsseldorf, welche unter der französischen Regierung das Lyzeum hieß, waren die Lehrer fast lauter katholische Geistliche, die sich alle mit ernster Güte meiner Geistesbildung annahmen; seit der preußischen Invasion, wo auch jene Schule den preußisch-griechischen Namen Gymnasium annahm, wurden die Priester allmählich durch weltliche Lehrer ersetzt.“","reference":"Mathias Bertram (Herausgeber): Deutsche Literatur von Lessing bis Kafka. Studienbibliothek. In: Digitale Bibliothek. 1. Auflage. 1, Directmedia Publishing GmbH, Berlin 2004, ISBN 3-89853-401-4 , Heinrich Heine: Geständnisse, vergleiche Heine-WuB Bd. 7, S. 148, Elektronische Seite 80.018"}],"idioms":["hinten Lyzeum, vorne Museum"],"collocations":[],"derivations":["Lyzeist","Lyzeistin"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Lyzeum","id":"a179d95e799788"},"006c-0079:faf3182cc57e3d":{"word":"Lys","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"Lys","de-DE":"Lys"},"forms":[],"senses":[{"definition":"Abkürzung von Lysin, eine Aminosäure"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lys","id":"faf3182cc57e3d"},"006c-0079:b0e697e74b31f6":{"word":"lydisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"ly·disch","de-DE":"ly·disch"},"forms":[{"form":"lydisch","tags":["Positiv"]},{"form":"lydische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"lydischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"lydischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"lydischer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"lydisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist lydisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist lydisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist lydisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind lydisch","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"eine alte Kirchentonart"},{"definition":"die historische, kleinasiatische Landschaft Lydien oder die Kultur der Lyder betreffend"}],"synonyms":[],"origins":["abgeleitet von der historischen, kleinasiatischen Küstenlandschaft Lydien"],"examples":[{"text":"„Tyrrhenos war nach der klassisch-antiken Mythologie der Sohn des lydischen Königs Athys.“","reference":"Wikipedia-Artikel „Tyrrhenos“"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"lydisch","id":"b0e697e74b31f6"},"006c-0079:a20f8ddacc8364":{"word":"Lymphe","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Lym·phe","de-DE":"Lym·phe"},"forms":[{"form":"Lymphe","tags":["Nominativ","Singular"]},{"form":"Lymphen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"wässrige Flüssigkeit, die im menschlichen Körper dem Nährstoff- und Abfallstofftransport dient"},{"definition":"vom Kalb gewonnener Impfstoff zur Pockenimpfung"}],"synonyms":[],"origins":["von lateinisch lympha ^(→ la) „klares Wasser“"],"examples":[{"text":"Die Lymphe ist eine gelbliche Flüssigkeit.","reference":""},{"text":"Die Vakzination gegen Pocken erfolgt mit Lymphen.","reference":""}],"idioms":[],"collocations":[],"derivations":["Lymphangiom","Lymphangitis","lymphatisch","Lymphbahn","Lymphdrainage","Lymphdrüse","Lymphfollikel","Lymphgefäß","Lymphgefäßentzündung","Lymphgefäßsystem","Lymphkapillare","Lymphknoten","Lymphknotenentzündung","Lymphkörperchen","Lymphödem","Lymphom","Lymphosarkom","Lymphozyten","Lymphstauung","Lymphströmung","Lymphzelle"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lymphe","id":"a20f8ddacc8364"},"006c-0079:827c9536f87d10":{"word":"Lysin","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Lys·in","de-DE":"Lys·in"},"forms":[{"form":"K","tags":["Kurzform"]},{"form":"Lys","tags":["Kurzform"]},{"form":"Lysin","tags":["Nominativ","Singular"]},{"form":"Lysins","tags":["Genitiv","Singular"]}],"senses":[{"definition":"eine proteinogene Aminosäure"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus dem gebundenen Lexem lys-, aus griechisch λύσις- (lysis-^☆) ^(→ grc) „Auflösung-“, und dem Suffix -in zur Kennzeichnung einer chemischen Verbindung. Der Biochemiker Edmund Drechsel (1843–1897) konnte im Jahr 1889 bei der Spaltung von Casein mithilfe von Salzsäure die Substanz isolieren, die er zunächst Lysatin und zwei Jahre später Lysin nannte."],"examples":[{"text":"„Die richtige Zusammensetzung dieser Aminosäure wurde 1891 durch seinen Schüler Max Siegfried veröffentlicht und die finale Aufklärung der Strukturformel erfolgte 1902 über die Synthese von Lysin durch den Nobelpreisträger Emil Fischer und seinen Assistenten Fritz Weigert.“","reference":"Wikipedia-Artikel „Lysin“ (Stabilversion)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lysin","id":"827c9536f87d10"},"006c-0079:41495dbdb32e62":{"word":"Lydisch","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Ly·disch","de-DE":"Ly·disch"},"forms":[{"form":"xld","tags":["Kurzform"]},{"form":"das Lydische","tags":["Nominativ","Singular"]},{"form":"(das) Lydisch","tags":["Nominativ","Singular"]},{"form":"(dem) Lydisch","tags":["Dativ","Singular"]},{"form":"(des) Lydisch","tags":["Genitiv","Singular"]},{"form":"dem Lydischen","tags":["Dativ","Singular"]},{"form":"des Lydischen","tags":["Genitiv","Singular"]},{"form":"(des) Lydischs","tags":["Genitiv","Singular"]}],"senses":[{"definition":"ausgestorbene Sprache, die in Anatolien vom Volk der Lyder gesprochen wurde"}],"synonyms":[],"origins":[],"examples":[{"text":"„Zur Schreibung des Lydischen wurde eine Schriftart verwendet, die einem ostgriechischen Alphabet sehr ähnlich ist.“","reference":"Wikipedia-Artikel „Lydische Sprache“"},{"text":"„Offenbar haben die Perser nicht gut Lydisch gesprochen, jedenfalls schien in den persischen Schulen der altsprachliche Zweig wenig gefragt[.]“","reference":"„Probleme der Währungspolitik“, Ernst Baltensperger, Werner Ehrlicher, Rudolf Richter, Duncker & Humblot, 1981"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lydisch","id":"41495dbdb32e62"},"006c-0079:33f6133df22242":{"word":"Lykanthropie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ly·k·an·thro·pie","de-DE":"Ly·k·an·thro·pie"},"forms":[{"form":"Lykanthropie","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Verwandlung eines Menschen in einen Werwolf, wie es in vielen Märchen und Sagen beschrieben wird"}],"synonyms":[],"origins":["von altgriechisch λύκος (lykos^☆) ^(→ grc) „Wolf“ und ἄνθρωπος (anthrōpos^☆) ^(→ grc) „Mensch“"],"examples":[{"text":"Ist die Lykanthropie wirklich nur ein Mythos?","reference":""},{"text":"„Hille ist wie besessen, er ähnelt fast einem von Lykanthropie Befallenen, der seine Schlußszene spielt, während rings um ihn bereits die schäbigen Kulissen abgebaut werden, und der sich der Unglaubwürdigkeit seiner Rolle bewußt ist.“","reference":"Heinz Rein: Finale Berlin. Roman. Ullstein, ohne Ortsangabe 2017, ISBN 978-3-548-28730-0, Seite 239 f. Originalausgabe 1947."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lykanthropie","id":"33f6133df22242"},"006c-0079:abd966e1aa6916":{"word":"Lychen","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Ly·chen","de-DE":"Ly·chen"},"forms":[{"form":"Lychens","tags":["Genitiv","Singular"]},{"form":"des Lychen","tags":["Genitiv","Singular"]},{"form":"des Lychens","tags":["Genitiv","Singular"]},{"form":"(das) Lychen","tags":["Nominativ","Singular"]},{"form":"(dem) Lychen","tags":["Dativ","Singular"]}],"senses":[{"definition":"eine Stadt in Brandenburg, Deutschland"}],"synonyms":[],"origins":[],"examples":[{"text":"Lychen liegt in Deutschlands Osten.","reference":""},{"text":"„Das 1903 gegründete Sanatorium liegt auf einer Halbinsel am Stadtrand von Lychen und ist seit 1933 auf die Heilung von Sportverletzungen und Gelenkerkrankungen spezialisiert.“","reference":"Anatol Regnier: Jeder schreibt für sich allein. Schriftsteller im Nationalsozialismus. 2. Auflage. btb, München 2022, ISBN 978-3-442-77183-7, Seite 249. 1. Auflage 2022."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lychen","id":"abd966e1aa6916"},"006c-0079:0fec689a553fd4":{"word":"lynchen","partOfSpeech":"Verb","gender":"","hyphenation":{"de-CH":"lyn·chen","de-DE":"lyn·chen"},"forms":[{"form":"haben","tags":["Hilfsverb","Perfekt"]},{"form":"lynch!","tags":["Imperativ","Singular"]},{"form":"lynche","tags":["Präsens"]},{"form":"lyncht","tags":["Präsens"]},{"form":"lynche!","tags":["Imperativ","Singular"]},{"form":"lynchen","tags":["Aktiv","Infinitiv","Präsens"]},{"form":"lynchst","tags":["Präsens"]},{"form":"lyncht!","tags":["Imperativ","Plural"]},{"form":"lynchte","tags":["Präteritum"]},{"form":"gelyncht","tags":["Partizip II","Perfekt"]},{"form":"lynchend","tags":["Partizip","Präsens","Aktiv"]},{"form":"du lynchst","tags":["2. Person","Singular","Präsens","Aktiv","Indikativ"]},{"form":"ich lynche","tags":["1. Person","Singular","Präsens","Aktiv","Indikativ"]},{"form":"ihr lyncht","tags":["2. Person","Plural","Präsens","Aktiv","Indikativ"]},{"form":"zu lynchen","tags":["Aktiv","erweitert","Infinitiv"]},{"form":"du lynchest","tags":["2. Person","Singular","Präsens","Aktiv","Konjunktiv I"]},{"form":"ich lynchte","tags":["1. Person","Singular","Präteritum","Aktiv","Indikativ"]},{"form":"ihr lynchet","tags":["2. Person","Plural","Präsens","Aktiv","Konjunktiv I"]},{"form":"sie lynchen","tags":["3. Person","Plural","Präsens","Aktiv","Indikativ"]},{"form":"wir lynchen","tags":["1. Person","Plural","Präsens","Aktiv","Indikativ"]},{"form":"du lynchtest","tags":["2. Person","Singular","Präteritum","Aktiv","Indikativ"]},{"form":"ihr lynchtet","tags":["2. Person","Plural","Präteritum","Aktiv","Indikativ"]},{"form":"lynchen Sie!","tags":["Imperativ","Höflichkeitsform","Präsens","Aktiv"]},{"form":"sie lynchten","tags":["3. Person","Plural","Präteritum","Aktiv","Indikativ"]},{"form":"wir lynchten","tags":["1. Person","Plural","Präteritum","Aktiv","Indikativ"]},{"form":"zu lynchende","tags":["Partizip","gerundive"]},{"form":"gelyncht sein","tags":["statal-passive","Infinitiv","Präsens"]},{"form":"zu lynchender","tags":["Partizip","gerundive"]},{"form":"gelyncht haben","tags":["Aktiv","Infinitiv","Perfekt"]},{"form":"habe gelyncht!","tags":["Imperativ","uncommon","2. Person","Singular","Perfekt","Aktiv"]},{"form":"habt gelyncht!","tags":["Imperativ","uncommon","2. Person","Plural","Perfekt","Aktiv"]},{"form":"gelyncht werden","tags":["Vorgangspassiv","Infinitiv","Präsens"]},{"form":"werde gelyncht!","tags":["Imperativ","uncommon","2. Person","Singular","Präsens","Vorgangspassiv"]},{"form":"zu lynchendes …","tags":["Partizip","gerundive"]},{"form":"du hast gelyncht","tags":["2. Person","Singular","Perfekt","Aktiv","Indikativ"]},{"form":"du wirst lynchen","tags":["2. Person","Singular","Futur I","Aktiv","Indikativ"]},{"form":"er/sie/es lynche","tags":["3. Person","Singular","Präsens","Aktiv","Konjunktiv I"]},{"form":"er/sie/es lyncht","tags":["3. Person","Singular","Präsens","Aktiv","Indikativ"]},{"form":"gelyncht zu sein","tags":["statal-passive","erweitert","Infinitiv"]},{"form":"werdet gelyncht!","tags":["Imperativ","uncommon","2. Person","Plural","Präsens","Vorgangspassiv"]}],"senses":[{"definition":"jemanden für eine Tat, die als Unrecht angesehen wird, ohne rechtskräftiges Gerichtsurteil schwer misshandeln und/oder töten"},{"definition":"sehr mit jemandem schimpfen"}],"synonyms":[],"origins":["das Verb wurde im 19. Jahrhundert aus dem amerikanisch-englischen lynch ^(→ en) entlehnt, das auf den Familiennamen Lynch zurückgeht. Als Grund hierfür wird angegeben, dass ein Farmer in Virginia im 18. Jahrhundert mit einem von ihm ernannten Gremium Recht gesprochen haben soll. Bei dieser Person kann es sich um William Lynch oder um Charles Lynch handeln."],"examples":[{"text":"Weil sie ihn für einen Vergewaltiger hielten, lynchten die Farmer den Pfarrer.","reference":""},{"text":"„Den ungarischen Ministerpräsidenten wollten sie lynchen, weil er einen Bauernjungen mit seinem Auto überfahren hat.“","reference":"Alfred Döblin: Berlin Alexanderplatz. Die Geschichte vom Franz Biberkopf. Deutscher Taschenbuch Verlag, München 1965, ISBN 3-423-00295-6, Seite 324. Erstveröffentlichung 1929."},{"text":"Du wirst von deiner Schwester gelyncht, wenn du dich noch einmal an ihrer Duschlotion bedienst.","reference":""}],"idioms":[],"collocations":[],"derivations":["Lyncher","Lynchjustiz","Lynchmob","Lynchmord"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"lynchen","id":"0fec689a553fd4"},"006c-0079:16ad8963650b47":{"word":"lyrisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"ly·risch","de-DE":"ly·risch"},"forms":[{"form":"lyrisch","tags":["Positiv"]},{"form":"lyrische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"lyrischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"lyrischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"lyrischer","tags":["Komparativ"]},{"form":"lyrisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"lyrischere","tags":["Komparativ","Nominativ","strong","Singular","feminine"]},{"form":"lyrischste","tags":["Superlativ","Nominativ","strong","Singular","feminine"]},{"form":"lyrischerem","tags":["Komparativ","Dativ","strong","Singular","masculine"]},{"form":"lyrischeren","tags":["Komparativ","Genitiv","strong","Singular","masculine"]},{"form":"lyrischerer","tags":["Komparativ","Nominativ","strong","Singular","masculine"]},{"form":"lyrischeres","tags":["Komparativ","Nominativ","strong","Singular","neuter"]},{"form":"lyrischstem","tags":["Superlativ","Dativ","strong","Singular","masculine"]},{"form":"lyrischsten","tags":["Superlativ","Genitiv","strong","Singular","masculine"]},{"form":"lyrischster","tags":["Superlativ","Nominativ","strong","Singular","masculine"]},{"form":"lyrischstes","tags":["Superlativ","Nominativ","strong","Singular","neuter"]},{"form":"am lyrischsten","tags":["Superlativ"]},{"form":"er ist lyrisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist lyrisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist lyrisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"er ist lyrischer","tags":["Komparativ","predicative","Singular","masculine"]},{"form":"es ist lyrischer","tags":["Komparativ","predicative","Singular","neuter"]},{"form":"sie sind lyrisch","tags":["Positiv","predicative","Plural"]},{"form":"sie ist lyrischer","tags":["Komparativ","predicative","Singular","feminine"]},{"form":"sie sind lyrischer","tags":["Komparativ","predicative","Plural"]},{"form":"er ist am lyrischsten","tags":["Superlativ","predicative","Singular","masculine"]},{"form":"es ist am lyrischsten","tags":["Superlativ","predicative","Singular","neuter"]},{"form":"sie ist am lyrischsten","tags":["Superlativ","predicative","Singular","feminine"]},{"form":"sie sind am lyrischsten","tags":["Superlativ","predicative","Plural"]}],"senses":[{"definition":"die Lyrik betreffend, in der Art der Lyrik oder ihr entsprechend"},{"definition":"gefühlvoll, gefühlsbetont, stimmungsvoll"},{"definition":"voller Stimmung und Empfindung"}],"synonyms":["atmosphärisch","dichterisch","poetisch","romantisch","stimmungsvoll"],"origins":["im frühen 18. Jahrhundert vom französisch lyrique ^(→ fr), über lateinisch lyricus ^(→ la) und griechisch λυρικός (lyrikós) ^(→ el) „zum Spiel der Lyra gehörig“ von griechisch λύρα (lýra) ^(→ el) „Lyra“"],"examples":[],"idioms":[],"collocations":[],"derivations":["Lyrik"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"lyrisch","id":"16ad8963650b47"},"006c-0079:13429fd8591d5c":{"word":"Lycopin","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Ly·co·pin","de-DE":"Ly·co·pin"},"forms":[{"form":"C","tags":["symbol"]},{"form":"H","tags":["symbol"]},{"form":"Lycopin","tags":["Nominativ","Singular"]},{"form":"Lykopin","tags":["alternative"]},{"form":"Lycopins","tags":["Genitiv","Singular"]},{"form":"E 160d","tags":["Kurzform"]}],"senses":[{"definition":"intensiv gelbroter, lipophiler (fettlöslicher), hitze- und lichtempfindlicher, pflanzlicher Farbstoff, der besonders in Tomaten, Paprika und Hagebutten vorkommt"}],"synonyms":[],"origins":["Lycopin geht auf neugriechisch λυκοπέρσικον (lykopérsikon) ^(→ el) „Tomate“ zurück – die Tomate kam erst 1596 aus Amerika nach Europa. Dies ist eine Anlehnung an die altgriechische Bezeichnung einer ägyptischen Pflanze λυκοπέρσικον (lykopersikon^☆) ^(→ grc), was wörtlich „Wolfspfirsich“ (Zusammensetzung von λυκός (lykos^☆) ^(→ grc) „Wolf“ und Περσικόν (Persikon^☆) ^(→ grc) „Pfirsich“), bedeutet (vgl. λυκοπέρσικον (lykopersikon^☆) ^(→ grc)). Diese Pflanze gab einen gelblichen Saft von starkem, aromatischem Geruch ab. Lycopin endet mit dem Suffix -in, das sächliche Substantive, meist im Bereich der Chemie oder Biochemie, bildet."],"examples":[{"text":"Lycopin wird als einer von der EU zugelassener Lebensmittelfarbstoff eingesetzt.","reference":""},{"text":"Wenngleich die Tomate weniger Karotine als in Aprikose, Sanddorn, Honigmelone oder Möhren enthält, so ist sie doch am reichsten an Lycopin (ca. 0,2 g/100 mg Tomatenmark).","reference":""},{"text":"Lycopin zeigt biologische Aktivität als Antioxidants, beeinflußt das Zellwachstum und moduliert sowohl die Genexpression wie die Immunität.","reference":""},{"text":"Heute weiß man: Diese Frucht mit Migrationshintergrund ist außerordentlich gesundheitsfördernd, voller Vitamin C, bei einem Wassergehalt von mehr als 90 Prozent kalorienarm, der sekundäre Pflanzenstoff Lycopin ein Radikalenfänger und, was medizinische Studien der letzten 20 Jahre zeigten, für die Krebsvorsorge zu empfehlen.","reference":"Alexander Kluy: Tomate: Rote Frucht wanderte aus Südamerika ein. In: Welt Online. 12. August 2010, ISSN 0173-8437 (URL) ."},{"text":"Lycopin wird am besten vom menschlichen Körper aufgenommen, wenn man Tomaten in Öl erhitzt.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lycopin","id":"13429fd8591d5c"},"006c-0079:f3572828f5101f":{"word":"Lyoner","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"Lyo·ner","de-DE":"Lyo·ner"},"forms":[{"form":"Lyoner","tags":["Positiv"]}],"senses":[{"definition":"sich auf die Stadt Lyon beziehend, in der Art und Weise dieses Ortes, aus Lyon kommend, stammend, Lyon betreffend, zu Lyon gehörend"}],"synonyms":["Fleischwurst"],"origins":[],"examples":[{"text":"Die Lyoner Stadtgeschichte reicht bis in die Römerzeit zurück.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Lyoner","id":"f3572828f5101f"},"006c-0079:fb473c63c8768a":{"word":"Lyoner","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Lyo·ner","de-DE":"Lyo·ner"},"forms":[{"form":"Lyoner","tags":["Nominativ","Singular"]},{"form":"Lyonern","tags":["Dativ","Plural"]},{"form":"Lyoners","tags":["Genitiv","Singular"]},{"form":"Lyonerin","tags":["feminine"]}],"senses":[{"definition":"(männliche) Person aus der französischen Stadt Lyon"},{"definition":"Brühwurst aus feinem Brät"}],"synonyms":["Fleischwurst"],"origins":["wohl nach der französischen Stadt Lyon benannt"],"examples":[{"text":"Jaques ist ein gebürtiger Lyoner.","reference":""},{"text":"Ich hätte gerne 200 Gramm Lyoner, geschnitten.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Lyoner","id":"fb473c63c8768a"},"006c-0079:4de193f9a189a3":{"word":"Lykien","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Ly·ki·en","de-DE":"Ly·ki·en"},"forms":[{"form":"Lykiens","tags":["Genitiv","Singular"]},{"form":"des Lykien","tags":["Genitiv","Singular"]},{"form":"des Lykiens","tags":["Genitiv","Singular"]},{"form":"(das) Lykien","tags":["Nominativ","Singular"]},{"form":"(dem) Lykien","tags":["Dativ","Singular"]}],"senses":[{"definition":"historische Landschaft im südwestlichen Kleinasien"}],"synonyms":[],"origins":[],"examples":[{"text":"„Noch während Römer und Makedonen sich bekämpften, unterwarf er im Jahr 197 v.Chr. einen Teil Lykiens mit der Stadt Xanthos, zog dann weiter nach Westen und Norden, wo er, unter Umgehung der rhodischen und pergamenischen Besitzungen in Kleinasien, Ephesos einnahm.“","reference":"Pedro Barceló: Kleine römische Geschichte. Sonderausgabe, 2., bibliographisch aktualisierte Auflage. Primus Verlag, Darmstadt 2012, ISBN 978-3534250967 , Seite 40."}],"idioms":[],"collocations":[],"derivations":["Lykier","lykisch"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lykien","id":"4de193f9a189a3"},"006c-0079:e1c54543de858f":{"word":"Lyssa","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Lys·sa","de-DE":"Lys·sa"},"forms":[{"form":"Lyssa","tags":["Nominativ","Singular"]}],"senses":[{"definition":"durch einen Virus verursachte Krankheit bei Tieren, insbesondere bei Hunden und Füchsen"}],"synonyms":["Tollwut"],"origins":[],"examples":[{"text":"Durch den Speichel eines an Lyssa erkrankten Tieres kann die Krankheit auf den Menschen übertragen werden.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Lyssa","id":"e1c54543de858f"},"006c-0079:7f3e4944167b9e":{"word":"Lyonerin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Lyo·ne·rin","de-DE":"Lyo·ne·rin"},"forms":[{"form":"Lyoner","tags":["masculine"]},{"form":"Lyonerin","tags":["Nominativ","Singular"]},{"form":"Lyonerinnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"(weibliche) Person aus der französischen Stadt Lyon"}],"synonyms":[],"origins":["Ableitung (Motion, Movierung) des Femininums aus der männlichen Form Lyoner mit dem Derivatem (Ableitungsmorphem) -in"],"examples":[{"text":"Marie ist (eine) gebürtige Lyonerin.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lyonerin","id":"7f3e4944167b9e"},"006c-0079:96041e655686e8":{"word":"Lyzeistin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ly·zei·stin","de-DE":"Ly·zei·stin"},"forms":[{"form":"Lyzeistin","tags":["Nominativ","Singular"]},{"form":"Lyzeistinnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Schülerin eines Lyzeums"}],"synonyms":[],"origins":["[1] Ableitung (speziell Motion, Movierung) von Lyzeist mit dem Derivatem (Ableitungsmorphem) -in"],"examples":[{"text":"„Schülerinnen, Lyzeistinnen, gehen dort Arm in Arm auf und ab, die Gymnasiasten fehlen nicht, und auch ältere Mädchen sind da, Mädchen von zwanzig, einundzwanzig Jahren.“","reference":"Hans Fallada: Bauern, Bonzen und Bomben. Roman. Aufbau, Berlin 2011, ISBN 978-3-7466-2793-9, Seite 423. Erstveröffentlichung 1931."},{"text":"„Als Lyzeistin schrieb Kudrjaschewa eine Schularbeit über die Sagen der nordischen Völker, in denen dieses Tier figurierte.“","reference":"Alina Kirillowna Kudrjaschewa#Werke Zugriff 19.9.13."},{"text":"„Unterzieht sich die Lyzeistin nach der Reifeprüfung einer Prüfung aus dem Latein der ersten sechs Klassen an einem öffentlichen Gymnasium, so wird sie zum Apothekerberufe zugelassen;…“","reference":"Joseph Loos: Enzyklopädisches Handbuch der Erziehungskunde. Zweiter Band: M - Z. Salzwasser, Paderborn 2012, ISBN 978-3-84600-433-3, Seite 9. Erstveröffentlichung 1908."},{"text":"„Die Filmkünstler entwickelten zusammen mit den Lyzeistinnen und Lyzeisten sowie deren Deutschlehrern ein Thema aus ihrer Alltagswelt und konnten dazu ihre eigenen kurzen Filme drehen.“","reference":"Goethe-Institut Taschkent: Aktuelles von PASCH 2012. Zugriff 19.9.13."},{"text":"„Der Akt setzt in einer Konditorei ein, wo sich mehrere Lyzeistinnen während ihrer Freistunden mit Gymnasiasten treffen.“","reference":"Gwendolyn Whittaker: Überbürdung - Subversion - Ermächtigung. Die Schule und die literarische Moderne 1880 - 1918. V & R unipress, Göttingen 2013, ISBN 978-3-8471-0095-9, Seite 311. = Dissertation, Konstanz 2012."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lyzeistin","id":"96041e655686e8"},"006c-0079:34967ac2fb4662":{"word":"Lyon","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Lyon","de-DE":"Lyon"},"forms":[{"form":"Lyons","tags":["Genitiv","Singular"]},{"form":"des Lyon","tags":["Genitiv","Singular"]},{"form":"des Lyons","tags":["Genitiv","Singular"]},{"form":"(das) Lyon","tags":["Nominativ","Singular"]},{"form":"(dem) Lyon","tags":["Dativ","Singular"]}],"senses":[{"definition":"südostfranzösische Großstadt am Zusammenfluss der Rhone und der Saône"}],"synonyms":[],"origins":[],"examples":[{"text":"Pierre stammt aus Lyon.","reference":""},{"text":"Ziehst Du bald wieder nach Lyon zurück?","reference":""},{"text":"Gibt es in Lyon eine Trabrennbahn?","reference":""},{"text":"„Wir reisten ab und gelangten in fünf Tagen nach Lyon, wo ich eine Woche blieb. Lyon ist eine sehr schöne Stadt, wo zu meiner Zeit keine drei oder vier adligen Häuser den Fremden offen standen, dafür fand man aber bei den Kaufleuten, Fabrikanten und Großhändlern, die viel reicher waren als die Adligen die beste Aufnahme, und die Gesellschaft lebt dort auf einem ausgezeichneten Fuß.“","reference":"Casanova: Erinnerungen, Band 2. In: Projekt Gutenberg-DE. 2, Georg Müller, 1911 (übersetzt von Heinrich Conrad), Siebentes Kapitel (URL, abgerufen am 20. Dezember 2021) . Alte Version im Internet-Archiv abrufbar. *"},{"text":"„Sie drohten mit Kapitalflucht, in diesem Fall mit Abwanderung nach Lyon.“","reference":"Bruno Preisendörfer: Als unser Deutsch erfunden wurde. Reise in die Lutherzeit. 7. Auflage. Galiani, Berlin 2016, ISBN 978-3-86971-126-3 , Seite 112."},{"text":"„Wir verabredeten uns für den nächsten Tag und entschieden uns dann für den Expresszug nach Lyon, der morgens abfuhr.“","reference":"Ernest Hemingway: Paris, ein Fest fürs Leben. A moveable feast. Die Urfassung. 18. Auflage. Rowohlt Taschenbuch Verlag, Reinbek 2024 (übersetzt von Werner Schmitz), ISBN 978-3-499-22702-8 , Zitat Seite 152 f. Englische Originalausgabe Scribner, New York 2009; deutsche Erstauflage 2012."},{"text":"„Einige Monate nach diesem Gespräch schickte Eiríkur seinen Großeltern ein Foto von sich und Tove, auf dem sie vor einem Restaurant auf einem in Sonnenlicht badenden Platz in Lyon lachend und offensichtlich glücklich ihre Biergläser heben.“","reference":"Jón Kalman Stefánsson: Dein Fortsein ist Finsternis. Roman. Piper, München 2024 (übersetzt von Karl-Ludwig Wetzig), ISBN 978-3-492-32059-7 , Seite 376. Isländisch 2020."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lyon","id":"34967ac2fb4662"},"006c-0079:2e19cc8266bc8a":{"word":"Lybien","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Ly·bi·en","de-DE":"Ly·bi·en"},"forms":[{"form":"Libien","tags":["variant"]},{"form":"Libyen","tags":["variant"]},{"form":"Lybyen","tags":["variant","archaic"]},{"form":"Lübien","tags":["alternative"]},{"form":"Lybiens","tags":["Genitiv","Singular"]},{"form":"des Lybien","tags":["Genitiv","Singular"]},{"form":"des Lybiens","tags":["Genitiv","Singular"]},{"form":"(das) Lybien","tags":["Nominativ","Singular"]},{"form":"(dem) Lybien","tags":["Dativ","Singular"]}],"senses":[{"definition":"ein Land in Nordafrika, westlich von Ägypten"},{"definition":"der afrikanische Kontinent"}],"synonyms":[],"origins":["Entstanden durch Metathese (Lautumstellung) aus Libyen, dieses über lateinisch Libya ^(→ la), Libyē ^(→ la) und griechisch Λιβύη (Libyē^☆) ^(→ grc) aus dem Altägyptischen."],"examples":[{"text":"„Er ging nach Lybien und floh von dort über Lampedusa nach Europa.“","reference":"2016 in Hamburg: Refugee Conference: „Uns wird nichts geschenkt“ – taz.de, am 30. Dezember  2015"},{"text":"„Dido hat sich ihre Herrschaftsposition in Lybien vor allem durch eigene Klugheit und politische Umsicht erarbeitet.“","reference":"Monika Schausten, Gender, Identität und Begehren: Zur Dido-Episode in Heinrichs von Veldeke „Eneit“, in: Manlîchiu wîp, wîplîch man: Zur Konstuktion der Kategorien ‚Körper‘ und ‚Geschlecht‘ in der deutschen Literatur des Mittelalters, hrsg. von Ingrid Bennewitz/Helmut Tervooren, erschienen als Beiheft zur Zeitschrift für deutsche Philologie 9, Berlin 1999, ISBN 3-503-04923-1, S. 150."},{"text":"„Die Blätter dienen in Lybien als Abführmittel.“","reference":"Heinz August Hoppe, Drogenkunde Bd. 1: Angiospermen, Berlin 1975, ISBN 3-11-003849-8, S. 197 s. v. C(aesalpinia) gilliesii."},{"text":"„Die begrenzte Vereinigung von Ägypten, Syrien und Lybien, der Klassenkampf und die Entwicklung der sozialistischen Revolution im Nahen Osten […]“","reference":"gleichnamige Überschrift aus: Die begrenzte Vereinigung von Ägypten, Syrien und Lybien, der Klassenkampf und die Entwicklung der sozialistischen Revolution im Nahen Osten: 24. April 1971; Die bürgerlich-nationalistische Regierung, die Erhebung der Guerilla in Ceylon und der chinesisch-sowjetische Konflikt: 5. Mai 1971. Resolutionen d. Internat. Sekretariats d. IV. Internationale; Band 2 von Edition Arbeiterstimme, Verlag: Gruppe Revolutionärer Kommunisten (Trotzkisten), 1971, 7 Seiten; siehe auch Google Books"},{"text":"„Mit der Zeit versandete das heutige Lybien wieder und die Bevölkerung suchte neues Fruchtland.“","reference":"Ahmed Muddathir, Die Industrialisierung der wirtschaftlich unterentwickelten afrikanischen Länder und ihre Auswirkungen auf die Weltwirtschaft. Ein Beitrag zur Lösung des Problems der wirtschaftlichen Unterentwicklung im Rahmen einer horizontalen internationalen Arbeitsteilung, Heft 31 der Reihe Volkswirtschaftliche Schriften, Berlin 1957, S. 51."},{"text":"„Auch erzählten ſie, was mir (alſo dem Herodot) nicht glaublich iſt, vielleicht aber Anderen, daß ſie, als ſie Lybien umſchifften, die Sonne zur Rechten geſehn hatten.“","reference":"H. Stiehler, Reiſeforſchungen auf africaniſchem Boden, in: Zum Feierabende. Blumen- und Fruchtſtücke für die reifere Jugend, Erſter Band, hrsg. von H. L. Stieler, Dresden 1856, S. 66"},{"text":"„Dieſe Inſel war faſt größer, als Lybien und Aſien; …“","reference":"Platon’s Timäos. Eine ächte Urkunde wahrer Phyſik, aus dem griechiſchen überſetzt und erläutert von Dr. K. J. Windiſchmann, Hadamar 1804, S. 35."}],"idioms":[],"collocations":[],"derivations":["Lybier","lybisch"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lybien","id":"2e19cc8266bc8a"},"006c-0079:b5ce6362dfdefc":{"word":"Lynn","partOfSpeech":"Vorname","gender":"die","hyphenation":{"de-CH":"Lynn","de-DE":"Lynn"},"forms":[{"form":"L.","tags":["Kurzform"]},{"form":"Lin","tags":["alternative"]},{"form":"Lyn","tags":["alternative"]},{"form":"Linn","tags":["alternative"]},{"form":"Lynn","tags":["Nominativ","Singular"]},{"form":"Lynna","tags":["variant"]},{"form":"Lynne","tags":["variant"]},{"form":"Lynns","tags":["Nominativ","Plural"]},{"form":"Caitlyn","tags":["variant"]},{"form":"Katelyn","tags":["variant"]},{"form":"Marilyn","tags":["variant"]}],"senses":[{"definition":"weiblicher und männlicher Vorname, geschlechtsmehrdeutige Verwendung"}],"synonyms":[],"origins":["Lynn wurde aus dem Englischen ins Deutsche übernommen. Es kann sich um eine moderne Kurzform von Linda oder Carolyn handeln oder aber möglicherweise auch um einen Namen mit angelsächsischem Ursprung und der Bedeutung ‚reißender Gebirgsbach‘.Es ist auch denkbar, dass der Name auf das walisische llyn ^(→ cy) ‚See‘ zurückgeht."],"examples":[{"text":"Lynn wurde mit drei Jahren adoptiert.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lynn","id":"b5ce6362dfdefc"},"006c-0079:5d6e8a775fe453":{"word":"Lynn","partOfSpeech":"Nachname","gender":"die","hyphenation":{"de-CH":"Lynn","de-DE":"Lynn"},"forms":[{"form":"Lynn","tags":["Nominativ","Singular","masculine"]},{"form":"Lynns","tags":["Genitiv","Singular","masculine"]},{"form":"dem Lynn","tags":["Dativ","Singular","masculine"]},{"form":"den Lynn","tags":["Akkusativ","Singular","masculine"]},{"form":"der Lynn","tags":["Nominativ","Singular","masculine"]},{"form":"des Lynn","tags":["Genitiv","Singular","masculine"]},{"form":"die Lynn","tags":["Nominativ","Singular","feminine"]},{"form":"den Lynns","tags":["Dativ","Plural"]},{"form":"der Lynns","tags":["Genitiv","Plural"]},{"form":"des Lynns","tags":["Genitiv","Singular","masculine"]},{"form":"die Lynns","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Familienname, Vorname"}],"synonyms":[],"origins":[],"examples":[{"text":"Frau Lynn ist ein Genie im Verkauf.","reference":""},{"text":"Herr Lynn wollte uns kein Interview geben.","reference":""},{"text":"Die Lynns fliegen heute nach Dublin.","reference":""},{"text":"Der Lynn trägt nie die Schals, die die Lynn ihm strickt.","reference":""},{"text":"Das kann ich dir aber sagen: „Wenn die Frau Lynn kommt, geht der Herr Lynn.“","reference":""},{"text":"Lynn kommt und geht.","reference":""},{"text":"Lynns kamen, sahen und siegten.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lynn","id":"5d6e8a775fe453"},"006c-0079:90d80dbb1e8cad":{"word":"Lynchjustiz","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Lynch·jus·tiz","de-DE":"Lynch·jus·tiz"},"forms":[{"form":"Lynchjustiz","tags":["Nominativ","Singular"]},{"form":"Lynch-Justiz","tags":["alternative"]}],"senses":[{"definition":"ungesetzliche schwere Bestrafung (durch Misshandeln oder Töten) ohne Rechtfertigung durch ein Gerichtsurteil"}],"synonyms":["Selbstjustiz","Volksjustiz"],"origins":["Das Wort ist seit dem 19. Jahrhundert belegt.","Determinativkompositum aus dem Stamm des Verbs lynchen und Justiz"],"examples":[{"text":"„Wenn so etwas wie die Drohung einer Lynchjustiz in der Luft gelegen hatte, jetzt war sie völlig verflogen.“","reference":"Ralph Giordano: Die Bertinis. Roman. 22. Auflage. Fischer Taschenbuch Verlag, Frankfurt/M. 2008, ISBN 978-3-596-25961-8, Seite 660 ."},{"text":"„Es kam zu Lynchjustiz, häufig in Form von necklacing.“","reference":"Trevor Noah: Farbenblind. 2. Auflage. Karl Blessing Verlag, München 2017 (Originaltitel: Born a Crime: Stories from a South African Childhood, übersetzt von Heike Schlatterer aus dem Englischen), ISBN 978-3-89667-590-3, Seite 22 .\nDie Kursivsetzung von »necklacing« wurde nicht übernommen."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Lynchjustiz","id":"90d80dbb1e8cad"},"006c-0079:ec40a09cf3db45":{"word":"Lyra","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Lyra","de-DE":"Lyra"},"forms":[{"form":"Lyra","tags":["Nominativ","Singular"]},{"form":"Lyren","tags":["Nominativ","Plural"]}],"senses":[{"definition":"der Kithara ähnliches altgriechisches Zupfinstrument mit fünf bis sieben Saiten"},{"definition":"ähnlich geformtes Glockenspiel beim Militär"},{"definition":"aus der Fidel entwickeltes und der Violine ähnliches Streichinstrument"},{"definition":"Drehleier"}],"synonyms":["Leier","Marsch-Glockenspiel","Militär-Glockenspiel","Militär-Lyra"],"origins":["über lateinisch lyra aus dem Griechischen"],"examples":[{"text":"Die Lira da gamba, ein Streichinstrument, das man beim Spielen zwischen den Knien hält, sollte an das antike Zupfinstrument \"Lyra\" erinnern.","reference":"Museum für Musikinstrumente. Abgerufen am 8. Juli 2015."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Lyra","id":"ec40a09cf3db45"},"006c-0079:c7a292691bc926":{"word":"Lymphstauung","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Lymph·stau·ung","de-DE":"Lymph·stau·ung"},"forms":[{"form":"Lymphstauung","tags":["Nominativ","Singular"]},{"form":"Lymphstauungen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"die Stauung von Lymphflüssigkeit im Körper"}],"synonyms":[],"origins":["Determinativkompositum aus dem Stamm „Lymph“ des Substantivs Lymphe und dem Substantiv Stauung"],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lymphstauung","id":"c7a292691bc926"},"006c-0079:dcc7551dd7d014":{"word":"Lymphströmung","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Lymph·strö·mung","de-DE":"Lymph·strö·mung"},"forms":[{"form":"Lymphströmung","tags":["Nominativ","Singular"]},{"form":"Lymphströmungen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"das Umherströmen der Lymphflüssigkeit im Körper"}],"synonyms":[],"origins":["Determinativkompositum aus dem Stamm „Lymph“ des Substantivs Lymphe und dem Substantiv Strömung"],"examples":[{"text":"„Die Lymphströmung wird durch verschiedene Komponenten bewirkt, die Strömungsgeschwindigkeit ist weit geringer als die des Blutes“","reference":"dtv-Brockhaus Lexikon in zwanzig Bänden. Erste Auflage. Elfter Band: Len–Mec, F.A. Brockhaus GmbH, Deutscher Taschenbuch Verlag GmbH, Mannheim, München 1989, ISBN 3-423-03311-8 , Seite 169, Artikel „Lymphgefäßsystem“"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lymphströmung","id":"dcc7551dd7d014"},"006c-0079:798aada21ffeee":{"word":"Lymphangiom","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Lymphan·gi·om","de-DE":"Lymphan·gi·om"},"forms":[{"form":"Lymphangiom","tags":["Nominativ","Singular"]},{"form":"Lymphangiome","tags":["Nominativ","Plural"]},{"form":"Lymphangioms","tags":["Genitiv","Singular"]},{"form":"Lymphangiomen","tags":["Dativ","Plural"]},{"form":"Lymphangiomes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Gefäßgeschwulst aus Lymphgefäßen verschiedener Größen"}],"synonyms":[],"origins":["Determinativkompositum aus dem Stamm „Lymph“ des Substantivs Lymphe und dem Substantiv Angiom"],"examples":[{"text":"Ein Lymphangiom ist meist gutartig.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lymphangiom","id":"798aada21ffeee"},"006c-0079:ec2e08c26659cf":{"word":"Lymphangitis","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Lymphan·gi·tis","de-DE":"Lymphan·gi·tis"},"forms":[{"form":"Lymphangitis","tags":["Nominativ","Singular"]},{"form":"Lymphangitiden","tags":["Nominativ","Plural"]}],"senses":[{"definition":"eine Entzündung der Lymphgefäße"}],"synonyms":["Lymphangiitis","Lymphgefäßentzündung"],"origins":[],"examples":[{"text":"Lymphangitis ist eine Entzündung der Lymphgefäße in Haut und Unterhaut, eine entzündliche Schwellung der Lymphknoten bezeichnet man hingegen als Lymphadenitis.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Lymphangitis","id":"ec2e08c26659cf"},"006c-0079:e905ff72089589":{"word":"Lymphadenitis","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Lympha·deni·tis","de-DE":"Lympha·deni·tis"},"forms":[{"form":"Lymphadenitis","tags":["Nominativ","Singular"]},{"form":"Lymphadenitiden","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Entzündung der Lymphknoten"}],"synonyms":["reaktive Lymphknotenschwellung"],"origins":["Wortkombination aus lateinisch lympha (klares Wasser) ^(→ la), ἀδήν (adēn^☆) ^(→ grc) „Drüse“ und dem nachgestellten Wortbildungselement altgriechisch -ῖτις (-itis^☆) ^(→ grc) mit der Bedeutung „Entzündung“"],"examples":[{"text":"„Neben einer bakteriellen unspezifischen Lymphadenitis gibt es auch eine virusassoziierte Lymphadenitis, die z.B. bei Infekten mit verschiedenen Herpesviren (Herpes simplex, Zytomegalievirus, EBV) auftritt.“","reference":"Hans-Peter Zenner: Praktische Therapie von HNO-Krankheiten: Operationsprinzipien, konservative Therapie, Chemo- und Radiochemotherapie, Arzneimitteltherapie, physikalische Therapie, Rehabilitation, psychosoziale Nachsorge; mit 109 Tabellen ; mit praktischen Therapieanleitungen, Methodenbeschreibungen, Rezepturen, Stuttgart Aufklärungsbögen und Übungsschemata für Patienten 2008 (Schattauer Verlag), ISBN 3794522648, Seite 424"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Lymphadenitis","id":"e905ff72089589"},"006c-0079:bba7b3982563c8":{"word":"Lymphödem","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Lymph·ödem","de-DE":"Lymph·ödem"},"forms":[{"form":"Lymphödem","tags":["Nominativ","Singular"]},{"form":"Lymphödeme","tags":["Nominativ","Plural"]},{"form":"Lymphödems","tags":["Genitiv","Singular"]},{"form":"Lymphödemen","tags":["Dativ","Plural"]}],"senses":[{"definition":"Verdickung der Haut infolge von Lymphstauungen"}],"synonyms":[],"origins":["Determinativkompositum aus dem Stamm „Lymph“ des Substantivs Lymphe und dem Substantiv Ödem"],"examples":[{"text":"Auch wenn sich die Operationstechniken in den vergangenen Jahren so weit verbessert haben, dass der »dicke Arm« (Lymphödem) nach einer Brustkrebsoperation immer seltener wird, gibt es doch keine Gewähr dafür, dass Sie nicht doch darunter leiden.","reference":"Fehlender Parameter (Hilfe) Abgerufen am 16. Februar 2016."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lymphödem","id":"bba7b3982563c8"},"006c-0079:53dd095b3bfab2":{"word":"Lyriker","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ly·ri·ker","de-DE":"Ly·ri·ker"},"forms":[{"form":"Lyriker","tags":["Nominativ","Singular"]},{"form":"Lyrikern","tags":["Dativ","Plural"]},{"form":"Lyrikers","tags":["Genitiv","Singular"]},{"form":"Lyrikerin","tags":["feminine"]}],"senses":[{"definition":"jemand, der lyrische Texte verfasst"}],"synonyms":["Barde","Dichter","Dichterling","Gedichteschreiber","Minnesänger","Musensohn","Poet","Reimeschmied","Spielmann","Versemacher","Verseschmied","Versschreiber"],"origins":["belegt seit dem 19. Jahrhundert","Ableitung von Lyrik mit dem Derivatem (Ableitungsmorphem) -er"],"examples":[{"text":"„Daß er hier als größter lebender deutscher Lyriker gefeiert wird, trägt ihm publizistische Attacken der Rechten in Deutschland ein.“","reference":"Manfred Flügge: Märchenruf von Westen. Deutsche Schriftsteller in Paris. In: Konturen. Magazin für Sprache, Literatur und Landschaft. Nummer Heft 4, 1993 , Seite 5-16, Zitat Seite 10."},{"text":"„Als Lyriker wurde Klabund im Jahre 1913 von dem berühmt-berüchtigten Alfred Kerr für dessen Zeitschrift »Pan« entdeckt.“","reference":"Jürgen Serke: Die verbrannten Dichter. Lebensgeschichten und Dokumente. 2. Auflage. Wallstein, Göttingen 2023, ISBN 978-3-8353-5388-6, Seite 115."},{"text":"„Im Zuge der Neuordnung wurde Anfang 1932 auch der Arzt, Lyriker und Essayist Gottfried Benn hinzugewählt und, als zweite Frau neben Ricarda Huch, die 47-jährige Lyrikerin und Prosaautorin Ina Seidel, die 1930 mit ihrem historischen Roman »Das Wunschkind« einen großen Erfolg errungen hatte.“","reference":"Anatol Regnier: Jeder schreibt für sich allein. Schriftsteller im Nationalsozialismus. 2. Auflage. btb, München 2022, ISBN 978-3-442-77183-7, Seite 18. 1. Auflage 2022."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Lyriker","id":"53dd095b3bfab2"},"006c-0079:81c499b95b68a7":{"word":"Lyder","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ly·der","de-DE":"Ly·der"},"forms":[{"form":"Lyder","tags":["Nominativ","Singular"]},{"form":"Lydern","tags":["Dativ","Plural"]},{"form":"Lyders","tags":["Genitiv","Singular"]},{"form":"Lydier","tags":["variant"]},{"form":"Lyderin","tags":["feminine"]}],"senses":[{"definition":"Bewohner der altertümlichen kleinasiatischen Landschaft Lydien"}],"synonyms":[],"origins":["Ableitung vom Stamm von Lydien mit dem Ableitungsmorphem -er"],"examples":[{"text":"„Die Lyder, ein Volk in Kleinasien, gelten als Erfinder der ersten Geldmünzen.“","reference":"wissen.de – Artikel „Spannende Geschichte: Die Geschichte des Geldes“"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lyder","id":"81c499b95b68a7"},"006c-0079:d1d507d3c0b99f":{"word":"Lysozym","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Lys·o·zym","de-DE":"Lys·o·zym"},"forms":[{"form":"Lysozym","tags":["Nominativ","Singular"]},{"form":"Lysozyme","tags":["Nominativ","Plural"]},{"form":"Lysozyms","tags":["Genitiv","Singular"]},{"form":"Lysozymen","tags":["Dativ","Plural"]}],"senses":[{"definition":"Enzym, das unter anderem in verschiedenen Sekreten des menschlichen Körpers vorkommt und eine antibakterielle Wirkung besitzt"}],"synonyms":["Muramidase"],"origins":[],"examples":[{"text":"„Schweißflüssigkeit enthält das antimikrobielle Enzym Lysozym.“","reference":"wissen.de – Bildwörterbuch „Körpereigenes Abwehrsystem: Leistungsstarke Selbsthilfe“"},{"text":"„Lysozym katalysiert die Hydrolyse von Bestandteilen der Bakterienwände und wirkt auf diese Weise bakteriostatisch auf grampositive und gramnegative Bakterien.“","reference":"Lexikon der Ernährung. Spektrum Akademischer Verlag, Heidelberg 2001 auf spektrum.de, „Muttermilch“"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Lysozym","id":"d1d507d3c0b99f"},"006c-0079:6b7e5ea79f08a9":{"word":"Lyrikerin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ly·ri·ke·rin","de-DE":"Ly·ri·ke·rin"},"forms":[{"form":"Lyriker","tags":["masculine"]},{"form":"Lyrikerin","tags":["Nominativ","Singular"]},{"form":"Lyrikerinnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"weibliche Person, die lyrische Texte verfasst"}],"synonyms":[],"origins":["Ableitung (speziell Motion, Movierung) von Lyriker mit dem Derivatem (Ableitungsmorphem) -in"],"examples":[{"text":"„Sie ist zugleich auch selbst als Lyrikerin hervorgetreten.“","reference":"Jochen A. Bär: Was ist lietrarisch an literarischer Sprache?. In: Sprachdienst. Nummer Heft 1, 2017 , Seite 56-57, Zitat Seite 56."},{"text":"„Ihr Vater war in Berlin ein bekannter Gynäkologe, sie selbst wurde eine begabte Lyrikerin.“","reference":"Jürgen Serke: Die verbrannten Dichter. Lebensgeschichten und Dokumente. 2. Auflage. Wallstein, Göttingen 2023, ISBN 978-3-8353-5388-6, Seite 47."},{"text":"„Im Zuge der Neuordnung wurde Anfang 1932 auch der Arzt, Lyriker und Essayist Gottfried Benn hinzugewählt und, als zweite Frau neben Ricarda Huch, die 47-jährige Lyrikerin und Prosaautorin Ina Seidel, die 1930 mit ihrem historischen Roman »Das Wunschkind« einen großen Erfolg errungen hatte.“","reference":"Anatol Regnier: Jeder schreibt für sich allein. Schriftsteller im Nationalsozialismus. 2. Auflage. btb, München 2022, ISBN 978-3-442-77183-7, Seite 18. 1. Auflage 2022."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lyrikerin","id":"6b7e5ea79f08a9"},"006c-0079:13251216aad7e8":{"word":"Lymphgeschwulst","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Lymph·ge·schwulst","de-DE":"Lymph·ge·schwulst"},"forms":[{"form":"Lymphgeschwulst","tags":["Nominativ","Singular"]},{"form":"Lymphgeschwülste","tags":["Nominativ","Plural"]},{"form":"Lymphgeschwülsten","tags":["Dativ","Plural"]}],"senses":[{"definition":"meist angeborene Geschwulst durch erweiterte Lymphgefäße, oft im Gesicht vorkommend"}],"synonyms":[],"origins":["Determinativkompositum aus dem Stamm „Lymph“ des Substantivs Lymphe und dem Substantiv Geschwulst"],"examples":[{"text":"Lymphgeschwülste können operativ entfernt werden.","reference":"nach: Der Neue Herder. In 2 Bänden. Herder Verlag, Freiburg 1949 , Band 1, Spalte 2542, Artikel „Lymphgeschwulst“"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lymphgeschwulst","id":"13251216aad7e8"},"006c-0079:473031e75d4bfe":{"word":"Lymphgefäß","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Lymph·ge·fäss","de-DE":"Lymph·ge·fäß"},"forms":[{"form":"Lymphgefäss","tags":["alternative","Switzerland","Liechtenstein"]},{"form":"Lymphgefäße","tags":["Nominativ","Plural"]},{"form":"Lymphgefäßen","tags":["Dativ","Plural"]},{"form":"Lymphgefäßes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"das Gefäßsystem der Wirbeltiere im Körper, in dem die Lymphe gesammelt und in den venösen Blutkreislauf zurückgeführt wird"}],"synonyms":[],"origins":["Determinativkompositum aus dem Stamm „Lymph“ des Substantivs Lymphe und dem Substantiv Gefäß"],"examples":[{"text":"„Der rechte Lymphgang ist viel schwächer und kürzer; er sammelt vor allem die Lymphgefäße der eben erwähnten rechten vorderen Körperpartie bis zur Brust.“","reference":"Portmann, Adolf: Einführung in die vergleichende Morphologie der Wirbeltiere, Basel: Schwabe 1959 [1948], S. 223; zitiert nach: Digitales Wörterbuch der deutschen Sprache „Lymphgefäß“"},{"text":"„Aber Gertruda W. leidet nicht an Elefantiasis, also jener Verdickung der Gliedmaßen, die durch Erkrankung der Venen und Lymphgefäße hervorgerufen wird, besonders in den Tropen.“","reference":"Ralph Giordano: Ostpreußen ade. Reise durch ein melancholisches Land. 3. Auflage. Deutscher Taschenbuch Verlag, München 1997, ISBN 3-423-30566-5, Seite 129 ."}],"idioms":[],"collocations":[],"derivations":["Lymphgefäßentzündung","Lymphgefäßsystem"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lymphgefäß","id":"473031e75d4bfe"},"006c-0079:ad4755e774ec17":{"word":"Lymphbahn","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Lymph·bahn","de-DE":"Lymph·bahn"},"forms":[{"form":"Lymphbahn","tags":["Nominativ","Singular"]},{"form":"Lymphbahnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Teil des Gefäßsystems im Körper der Wirbeltiere, in dem die Lymphe gesammelt und in den venösen Blutkreislauf zurückgeführt wird"}],"synonyms":[],"origins":["Determinativkompositum aus dem Stamm „Lymph“ des Substantivs Lymphe und dem Substantiv Bahn"],"examples":[{"text":"„Hier sei besonders erwähnt, daß die Fette aus den Darmzotten in die Lymphbahn weitergeführt werden und, ohne die Leber zu passieren, in die Blutbahn gelangen.“","reference":"Kölling, Alfred: Fachbuch für Kellner, Leipzig: Fachbuchverl. VEB 1962 [1956], S. 90; zitiert nach: Digitales Wörterbuch der deutschen Sprache „Lymphbahn“"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lymphbahn","id":"ad4755e774ec17"},"006c-0079:65ed8df9d7a215":{"word":"Lymphozyt","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Lym·pho·zyt","de-DE":"Lym·pho·zyt"},"forms":[{"form":"Lymphozyt","tags":["Nominativ","Singular"]},{"form":"Lymphozyten","tags":["Nominativ","Plural"]}],"senses":[{"definition":"in den Lymphknoten, den Mandeln oder der Milz gebildete weiße Blutzelle, die im Körper der Abwehr von Giftstoffen, Bakterien oder Viren dient"}],"synonyms":[],"origins":[],"examples":[{"text":"„In jedem Fall stimuliert ein Fremdeiweiß nur in einem Teil der Lymphozyten die Produktion der zugehörigen Antikörper.“","reference":"Bresch, Carsten: Klassische und molekulare Genetik, Berlin u. a.: Springer 1965 [1964], S. 200; zitiert nach: Digitales Wörterbuch der deutschen Sprache „Lymphozyt“"},{"text":"„Damit soll in der Tat das Infektionsrisiko für Kinder, denen der Lymphozyt fehlt drastisch reduziert und somit wiederholte vorbeugende Behandlungen mit Antibiotika, die zu einer Antibiotikaresistenz führen können, vermieden werden.“","reference":"www.fides.org, gecrawlt am 29.12.2010; zitiert nach: Uni Leipzig: Wortschatz-Portal „Lymphozyt“"},{"text":"„Die adaptive Immunantwort wird von Lymphozyten vermittelt. Sie zeichnet sich durch eine hohe Spezifität gegen bestimmte Antigene aus und beinhaltet eine Gedächtnisfunktion.“","reference":"Deutsches Zentrum für Infektionsforschung, Glossar. Abgerufen am 18. Mai 2020."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lymphozyt","id":"65ed8df9d7a215"},"006c-0079:b54b6321102682":{"word":"Lymphkörperchen","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Lymph·kör·per·chen","de-DE":"Lymph·kör·per·chen"},"forms":[{"form":"Lymphkörperchen","tags":["Nominativ","Singular"]},{"form":"Lymphkörperchens","tags":["Genitiv","Singular"]}],"senses":[{"definition":"in den Lymphknoten, den Mandeln oder der Milz gebildete weiße Blutzellen, die im Körper der Abwehr von Giftstoffen, Bakterien oder Viren dienen"}],"synonyms":[],"origins":["Determinativkompositum aus dem Stamm „Lymph“ des Substantivs Lymphe und dem Substantiv Körperchen"],"examples":[{"text":"„Nur tritt die erstere, welche hüllenlose Einzelzellen voraussetzt, in den Zellverbänden der Metazoën natürlich sehr zurück und kommt hauptsächlich bei der Bewegung von freien Einzelzellen im Körper vor: die Eier mancher niederer Metazoën, der Schwämme und Cölenteraten, können auf diese Weise ihre Stelle im Körper verändern; auch enthält die Leibesflüssigkeit oft freie Zellen, denen noch amöboide Bewegung zukommt, wie die Lymphkörperchen der Wirbeltiere.“","reference":"Hesse, Richard: Der Tierkörper als selbständiger Organismus, Leipzig u. a.: B. G. Teubner 1910, S. 157; zitiert nach: Digitales Wörterbuch der deutschen Sprache „Lymphkörperchen“"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lymphkörperchen","id":"b54b6321102682"},"006c-0079:2840a05100e7ba":{"word":"Lymphzelle","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Lymph·zel·le","de-DE":"Lymph·zel·le"},"forms":[{"form":"Lymphzelle","tags":["Nominativ","Singular"]},{"form":"Lymphzellen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"in den Lymphknoten, den Mandeln oder der Milz gebildete weiße Blutzelle, die im Körper der Abwehr von Giftstoffen, Bakterien oder Viren dient"}],"synonyms":[],"origins":["Determinativkompositum aus dem Stamm „Lymph“ des Substantivs Lymphe und dem Substantiv Zelle"],"examples":[{"text":"„Schon vor einiger Zeit haben amerikanische Forscher den „Ankerplatz“ (im Fachjargon: Rezeptor) für die Viren auf der Oberfläche dieser Lymphzellen entdeckt: eine Eiweißstruktur mit dem Namen T4-Antigen.“","reference":"Die Zeit, 28.02.1986, Nr. 10; zitiert nach: Digitales Wörterbuch der deutschen Sprache „Lymphzelle“"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lymphzelle","id":"2840a05100e7ba"},"006c-0079:bd601a79cc071e":{"word":"Lymphogranulom","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Lym·pho·gra·nu·lom","de-DE":"Lym·pho·gra·nu·lom"},"forms":[{"form":"Lymphogranulom","tags":["Nominativ","Singular"]},{"form":"Lymphogranulome","tags":["Nominativ","Plural"]},{"form":"Lymphogranuloms","tags":["Genitiv","Singular"]},{"form":"Lymphogranulomen","tags":["Dativ","Plural"]}],"senses":[{"definition":"meist an den Halslymphoknoten beginnende, auf ausgedehnte Drüsengruppen weiter übergreifende krebsartige Wucherung von Lymphogewebe"}],"synonyms":["Hodgkin-Lymphom","Hodgkinsche Krankheit","Lymphogranulomatose","Morbus Hodgkin"],"origins":[],"examples":[{"text":"Durch Behandlung mit Röntgen- und Radiumstrahlen […] wird oft ein jahrelang anhaltender Rückgang des Lymphogranuloms erreicht.","reference":"nach: Der Neue Herder. In 2 Bänden. Herder Verlag, Freiburg 1949 , Band 1, Spalte 2542, Artikel „Lymphogranulom“"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Lymphogranulom","id":"bd601a79cc071e"},"006c-0079:750187bf9b7a3e":{"word":"Lymphosarkom","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Lym·pho·sar·kom","de-DE":"Lym·pho·sar·kom"},"forms":[{"form":"Lymphosarkom","tags":["Nominativ","Singular"]},{"form":"Lymphosarkome","tags":["Nominativ","Plural"]},{"form":"Lymphosarkoms","tags":["Genitiv","Singular"]},{"form":"Lymphosarkomen","tags":["Dativ","Plural"]}],"senses":[{"definition":"bösartiges Sarkom von Lymphknoten aus in das Nachbargewebe hinein. (Veraltete Bezeichnung, laut heutiger Definition sind Sarkome von Binde und Stützgewebe ausgehend. Früher als Lymphosarkome bezeichnete Erkrankungen entsprechen den heutigen Lymphomen.)"}],"synonyms":["Lymphdrüsenkrebs","maligne Lymphome"],"origins":[],"examples":[{"text":"„Nach einem Herzinfarkt, den er bereits 1956 erlitt, wird Lymphosarkom, eine von den Lymphknoten ausgehende Krebserkrankung, festgestellt.“","reference":"Schäfer, Lothar u. Schnelle, Thomas: Ludwik Flecks Begründung der soziologischen Betrachtungsweise in der Wissenschaftstheorie. In: dies. (Hgg.) Entstehung und Entwicklung einer wissenschaftlichen Tatsache, Frankfurt a. M.: Suhrkamp 1980, S. 17; zitiert nach: Digitales Wörterbuch der deutschen Sprache „Lymphosarkom“"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Lymphosarkom","id":"750187bf9b7a3e"},"006c-0079:8bb5d96ef7f8c8":{"word":"Lymphdrüsenkrebs","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Lymph·drü·sen·krebs","de-DE":"Lymph·drü·sen·krebs"},"forms":[{"form":"Lymphdrüsenkrebs","tags":["Nominativ","Singular"]},{"form":"Lymphdrüsenkrebse","tags":["Nominativ","Plural"]},{"form":"Lymphdrüsenkrebsen","tags":["Dativ","Plural"]},{"form":"Lymphdrüsenkrebses","tags":["Genitiv","Singular"]}],"senses":[{"definition":"bösartiges Sarkom von Lymphknoten aus in das Nachbargewebe hinein"}],"synonyms":["Lymphosarkom","maligne Lymphome"],"origins":["Determinativkompositum aus den Substantiven Lymphdrüse und Krebs sowie dem Fugenelement -n"],"examples":[{"text":"„Im vorigen November war bei dem Sänger von Hits wie \"Biene Maja\" und \"Schicksalsmelodie\" Lymphdrüsenkrebs festgestellt worden.“","reference":"Die Zeit, 11.10.2016 (online); zitiert nach: Digitales Wörterbuch der deutschen Sprache „Lymphdrüsenkrebs“"},{"text":"„Heute reagiert der Körper der jungen Frau, die noch dazu seit einer Chemotherapie wegen Lymphdrüsenkrebs vor vier Jahren an den Rollstuhl gefesselt ist, allergisch auf fast alle Gerüche.“","reference":"www.donaukurier.de, gecrawlt am 27.12.2010; zitiert nach: Uni Leipzig: Wortschatz-Portal „Lymphdrüsenkrebs“"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Lymphdrüsenkrebs","id":"8bb5d96ef7f8c8"},"006c-0079:c5ba5406c685cd":{"word":"Lymphdrüse","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Lymph·drü·se","de-DE":"Lymph·drü·se"},"forms":[{"form":"Lymphdrüse","tags":["Nominativ","Singular"]},{"form":"Lymphdrüsen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Filterstation für die Lymphe oder das Gewebewasser im Körper"}],"synonyms":["Lymphknoten"],"origins":["Determinativkompositum aus dem Stamm von Lymphe und dem Substantiv Drüse"],"examples":[{"text":"„Nun treten beim Kindergartenkind, also etwa von drei bis fünf Jahren, die Lymphdrüsen am Hals deutlich hervor und sind zusätzlich Sitz von Entzündungen.“","reference":"Schücking, Beate: Wir machen unsere Kinder krank, München: List 1971, S. 156; zitiert nach: Digitales Wörterbuch der deutschen Sprache „Lymphdrüse“"},{"text":"„Die Lymphdrüsen röten sich und werden groß wie Hühnereier.“","reference":"Jens Rehn, Nachwort von Ursula März: Nichts in Sicht. Schöffling, Frankfurt/Main 2018, ISBN 978-3-89561-149-0, Seite 7. Erstmals 1954 erschienen."},{"text":"„Das Fieber der Kranken sank, ihre Lymphdrüsen schwollen ab.“","reference":"Johann Grolle: Menschenversuche im Paradies. In: Eva-Maria Schnurr, Frank Patalong (Herausgeber): »Deutschland, deine Kolonien«: Geschichte und Gegenwart einer verdrängten Zeit. 2. Auflage. Deutsche Verlags-Anstalt, München 2022, ISBN 978-3-421-07002-9, Seite 158-167, Zitat Seite 165."}],"idioms":[],"collocations":[],"derivations":["Lymphdrüsenkrebs"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Lymphdrüse","id":"c5ba5406c685cd"},"006c-0079:d4162b07499cce":{"word":"lymphatisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"lympha·tisch","de-DE":"lympha·tisch"},"forms":[{"form":"lymphatisch","tags":["Positiv"]},{"form":"lymphatische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"lymphatischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"lymphatischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"lymphatischer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"lymphatisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist lymphatisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist lymphatisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist lymphatisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind lymphatisch","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"zum Lymphsystem gehörig, das Lymphsystem betreffend"}],"synonyms":[],"origins":[],"examples":[{"text":"„Ebenso hoch ist die Überlebenschance bei der akuten lymphatischen Leukämie von Kindern.“","reference":"Süddeutsche Zeitung, 16.06.1998; zitiert nach: Digitales Wörterbuch der deutschen Sprache „lymphatisch“"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"lymphatisch","id":"d4162b07499cce"},"006c-0079:179380e1568294":{"word":"Lysergsäurediäthylamid","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Lys·erg·säu·re·di·äthyl·amid","de-DE":"Lys·erg·säu·re·di·äthyl·amid"},"forms":[{"form":"Lysergsäurediethylamid","tags":["variant"]},{"form":"Lysergsäurediäthylamid","tags":["Nominativ","Singular"]},{"form":"Lysergsäurediäthylamids","tags":["Genitiv","Singular"]}],"senses":[{"definition":"halluzinogene Droge"}],"synonyms":[],"origins":[],"examples":[{"text":"„Denn Lysergsäurediäthylamid ist eine psychedelische Droge, sie kann in die luftigsten Unwirklichkeiten entführen und sie kann den Konsumenten der winzigen Teile in die Hölle jagen.“","reference":"Andreas Altmann: Gebrauchsanweisung für die Welt. 8. Auflage. Piper, München/Berlin/Zürich 2016, ISBN 978-3-492-27608-5, Seite 106. Erstauflage 2012."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lysergsäurediäthylamid","id":"179380e1568294"},"006c-0079:e60a6f4c1bab3c":{"word":"Lycopodiophytina","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Ly·co·po·dio·phyti·na","de-DE":"Ly·co·po·dio·phyti·na"},"forms":[{"form":"Lycopodiophytina","tags":["Nominativ","Plural"]}],"senses":[{"definition":"der wissenschaftliche Name der Bärlapppflanzen"}],"synonyms":[],"origins":["nach dem von Linné eingeführten Gattungsnamen „Lycopodium“ zu altgriechisch λυκόπους (lykopus^☆) ^(→ grc) „Wolfsfuß“ und dem Suffix -phytina, das eine Unterabteilung im Pflanzenreich anzeigt"],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lycopodiophytina","id":"e60a6f4c1bab3c"},"006c-0079:3ae1152fed936f":{"word":"Lydien","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Ly·di·en","de-DE":"Ly·di·en"},"forms":[{"form":"Lydiens","tags":["Genitiv","Singular"]},{"form":"des Lydien","tags":["Genitiv","Singular"]},{"form":"des Lydiens","tags":["Genitiv","Singular"]},{"form":"(das) Lydien","tags":["Nominativ","Singular"]},{"form":"(dem) Lydien","tags":["Dativ","Singular"]}],"senses":[{"definition":"antike Landschaft an der Mittelmeerküste Kleinasiens in der heutigen Türkei"},{"definition":"antikes Königreich"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lydien","id":"3ae1152fed936f"},"006c-0079:3933d2e0705ca4":{"word":"lykisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"ly·kisch","de-DE":"ly·kisch"},"forms":[{"form":"lykisch","tags":["Positiv"]},{"form":"lykische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"lykischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"lykischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"lykischer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"lykisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist lykisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist lykisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist lykisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind lykisch","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"die kleinasiatische Region Lykien und/oder die Lykier betreffend, von ihnen stammend"},{"definition":"zu der Sprache der Lykier (Lykisch) gehörig, in dieser Sprache verfasst"}],"synonyms":[],"origins":[],"examples":[{"text":"Er bewundert die lykische Kunst.","reference":""},{"text":"Sie untersucht lykische Inschriften.","reference":""},{"text":"Die Bedeutung dieses lykischen Wortes ist umstritten.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"lykisch","id":"3933d2e0705ca4"},"006c-0079:fc0d3339e7efec":{"word":"Lysimeter","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Lys·i·me·ter","de-DE":"Lys·i·me·ter"},"forms":[{"form":"Lysimeter","tags":["Nominativ","Singular"]},{"form":"Lysimetern","tags":["Dativ","Plural"]},{"form":"Lysimeters","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Gerät zum Messen der Versickerung und Verdunstung im Erdboden"}],"synonyms":[],"origins":[],"examples":[{"text":"„Probleme ergeben sich in der Vergleichbarkeit der Modellergebnisse mit Messwerten des Lysimeters an Niederschlagstagen.“","reference":"Joachim Gurtz: Auswirkungen von klimatischen Variationen auf Wasserhaushalt und Abfluss im Flussgebiet des Rheins. vdf Hochschulverlag AG, 1997, ISBN 978-3-7281-2396-1, Seite 48 (Zitiert nach Google Books)"},{"text":"„Das Wassergefäß des Lysimeters befindet sich in einer kälteren Schicht des Bodens als die Erde des Lysimeters. Das die Erde durchziehende wärmere Wasser verdunstet an der Unterseite der Erdschicht in den Raum des Wassersbehälters hinein […].“","reference":"Die Landwirtschaftlichen versuchs-stationen. G. Schönfeld (C.A. Werner), 1862, Seite 282 (Zitiert nach Google Books)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lysimeter","id":"fc0d3339e7efec"},"006c-0079:49fa851d027a62":{"word":"Lykopin","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Ly·ko·pin","de-DE":"Ly·ko·pin"},"forms":[{"form":"C","tags":["symbol"]},{"form":"H","tags":["symbol"]},{"form":"Lycopin","tags":["alternative","jargon"]},{"form":"Lykopin","tags":["Nominativ","Singular"]},{"form":"Lykopins","tags":["Genitiv","Singular"]}],"senses":[{"definition":"intensiv gelbroter, lipophiler (fettlöslicher), hitze- und lichtempfindlicher, pflanzlicher Farbstoff, der besonders in Tomaten, Paprika und Hagebutten vorkommt"}],"synonyms":[],"origins":["Lykopin geht auf griechisch λυκοπέρσικον (lykopérsikon) ^(→ el) „Tomate“ zurück – die Tomate kam erst 1596 aus Amerika nach Europa. Dies ist eine Anlehnung an die altgriechische Bezeichnung einer ägyptischen Pflanze λυκοπέρσικον (lykopersikon) ^(→ el), was wörtlich „Wolfspfirsich“ (Zusammensetzung von λυκός (lykos^☆) ^(→ grc) „Wolf“ und Περσικόν (Persikon^☆) ^(→ grc) „Pfirsich“), bedeutet. Diese Pflanze gab einen gelblichen Saft von starkem, aromatischem Geruch ab. Lykopin endet mit dem Suffix -in, das sächliche Substantive, meist im Bereich der Chemie oder Biochemie, bildet"],"examples":[{"text":"Lykopin soll aufgrund seiner antioxidativen Eigenschaften zellprotektive Wirkung haben und wird daher mit dem Schutz von Herz, Augen und Prostata beworben.","reference":"György Irmey, Anna-Luise Jordan, Hans Stieber: Lykopin - das \"Tomaten-Vitamin\"? verbraucherzentrale.de, 7. Oktober 2021, abgerufen am 5. April 2022."},{"text":"Allerdings weisen die Forscher explizit darauf hin, dass die Wirkung-Dosis-Beziehung nicht für isoliertes Lykopin, wie es in Nahrungsergänzungsmittel eingesetzt wird, gilt.","reference":""},{"text":"Besonders reich an Lykopin sind Guaven, Hagebutten, rosa Grapefruits und Tomaten.","reference":""},{"text":"Lykopin senkt das Krebsrisiko, und zwar besonders bei Krebsarten des Verdauungstrakts.","reference":"110 wirksame Behandlungsmöglichkeiten bei Krebs. Georg Thieme Verlag (zitiert nach Google Books, abgerufen am 5. April 2022) ."},{"text":"Auf Grund welcher Prozesse der Schutz durch Lykopin besteht, ist noch nicht erforscht, doch ist bekannt, dass es das Karotinoid mit der größten antioxidativen Wirkung ist.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lykopin","id":"49fa851d027a62"},"006c-0079:97f9be56fba71b":{"word":"Lyrics","partOfSpeech":"Substantiv","gender":"","hyphenation":{"de-CH":"Ly·rics","de-DE":"Ly·rics"},"forms":[{"form":"Lyrics","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Text eines Musikstücks"}],"synonyms":["Liedtext","Songtext","Text"],"origins":["aus gleichbedeutend englisch lyrics ^(→ en)"],"examples":[{"text":"„Immer findet sich eine kleine rhythmische Verschiebung, eine Sprachspielerei im Text – obwohl Scotts Lyrics heute sicher auf dem woken Scheiterhaufen als sexistisch verbrannt würden – […].“","reference":"Philip Cassier: Wie das Album „Back in Black“ zu ihrem größten Hit wurde. In: Welt Online. 25. Juli 2022, ISSN 0173-8437 (URL, abgerufen am 16. November 2022) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Lyrics","id":"97f9be56fba71b"},"006c-0079:ce925da2bc1f49":{"word":"Lymekrankheit","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ly·me·krank·heit","de-DE":"Ly·me·krank·heit"},"forms":[{"form":"Lymekrankheit","tags":["Nominativ","Singular"]},{"form":"Lyme-Krankheit","tags":["variant"]},{"form":"Lymekrankheiten","tags":["Nominativ","Plural"]}],"senses":[{"definition":"eine durch Borrelien ausgelöste und durch Zecken übertragene Infektionskrankheit"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Lyme (US-amerikanischer Ort, in dem das Krankheitsbild 1975 erstmals beschrieben wurde) und Krankheit"],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lymekrankheit","id":"ce925da2bc1f49"},"006c-0079:836973aef7e45f":{"word":"Lynchmob","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Lynch·mob","de-DE":"Lynch·mob"},"forms":[{"form":"Lynchmob","tags":["Nominativ","Singular"]},{"form":"Lynchmobs","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Mob, der versucht, jemanden zu lynchen"}],"synonyms":[],"origins":["Determinativkompositum aus dem Stamm des Verbs lynchen und dem Substantiv Mob"],"examples":[{"text":"„Lynchmobs hatten sicher gern Countrymusik gehört, als sie ihre schwarzen Opfer aufknüpften.“","reference":"Viet Thanh Nguyen: Der Sympathisant. Heyne, München 2018, ISBN 978-3-453-43960-3, Seite 263 ."},{"text":"„Die Gewalt machte auch vor dem Kotel-Schamasch Glazstein nicht halt, der angegriffen wurde und nur knapp einem Lynchmob entkam.“","reference":"Joseph Croitoru: Al-Aqsa oder Tempelberg. Der ewige Kampf um Jerusalems heilige Stätten. C.H.Beck, München 2021, ISBN 978-3-406-76585-8, Seite 140 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lynchmob","id":"836973aef7e45f"},"006c-0079:42198d845588b2":{"word":"Lynchmord","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Lynch·mord","de-DE":"Lynch·mord"},"forms":[{"form":"Lynchmord","tags":["Nominativ","Singular"]},{"form":"Lynchmorde","tags":["Nominativ","Plural"]},{"form":"Lynchmords","tags":["Genitiv","Singular"]},{"form":"Lynchmorden","tags":["Dativ","Plural"]},{"form":"Lynchmordes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Mord, bei dem das Opfer (meist durch eine Menschenmenge) grausam misshandelt und getötet wird"}],"synonyms":[],"origins":["Determinativkompositum aus dem Stamm des Verbs lynchen und dem Substantiv Mord"],"examples":[{"text":"„Betrachtet man die rassistischen Verbrechen seit dem Beginn des 19. Jahrhunderts, so stellt man fest, dass es sich dabei meist um höchst symbolische Taten mit großer Öffentlichkeitswirkung handelt. Ein Lynchmord soll eine öffentliche Demonstration sein und auch von der Öffentlichkeit als solche wahrgenommen werden.“","reference":"John Douglas/Mark Olshaker: Mindhunter. Die spektakulärsten Fälle der FBI-Spezialeinheit für Serienverbrechen. Riva, München 2020, ISBN 978-3-7423-1299-0, Seite 312 ."},{"text":"„Richter Anwar Nussaibeh hielt Lynchmorde für weniger abscheulich als die Regierungsmaßnahmen zur Unterdrückung des arabischen Aufstands, denn auch wenn Gewalt immer denselben Gefühlen von Angst und Hass entspringe, sei immerhin das Lynchen nicht vom Gesetz sanktioniert.“","reference":"Tom Segev: Es war einmal ein Palästina. Juden und Araber vor der Staatsgründung Israels. Siedler, München 2005, ISBN 978-3-886-80805-2, Seite 463 ."},{"text":"„Er war eines Tages mit der Theorie dahergekommen, dass das Mal, das Gott auf Kains Stirn gezeichnet hatte, in Wirklichkeit die schwarze Haut war und dass alles Schlimme, was den Negern widerfahren war - Sklaverei, Lynchmorde, Jim Crow -, die Folge der Tatsache war, dass sie Nachkommen von Kain waren.“","reference":"Matt Ruff: Lovecraft Country. Hanser, München 2018, ISBN 978-3446259447, Seite 406 ."},{"text":"„›Wir sind hier in Nigeria, Folake‹, sagte ich mit sarkastischem Unterton. ›Da gräbst du nicht die Details eines Lynchmords aus in der Hoffnung, einen Bestseller daraus zu machen.‹“","reference":"Femi Kayode: Lightseekers. btb, München 2022, ISBN 978-3-442-77011-3, Seite 14 ."},{"text":"„Er erzählt eine ziemlich lange Geschichte aus den Lebenserinnerungen seines Großvaters über einen Lynchmord in Georgia um das Jahr 1906, bei dem ein schwarzer Prediger mit glühender Kohle an Armen und Beinen verbrannt wurde und dann einen Schuss in den Hinterkopf bekam, als er immer noch nichts über seine Bestrebungen verraten wollte, die Arbeiter in den Baumwollspinnereien zu organisieren.“","reference":"Stephen L. Carter: Schachmatt. Rowohlt, Reinbek bei Hamburg 2010, ISBN 978-3-499-25472-7, Seite 437 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lynchmord","id":"42198d845588b2"},"006c-0079:5617ed49ac3a41":{"word":"Lyrikband","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ly·rik·band","de-DE":"Ly·rik·band"},"forms":[{"form":"Lyrikband","tags":["Nominativ","Singular"]},{"form":"Lyrikbands","tags":["Genitiv","Singular"]},{"form":"Lyrikbände","tags":["Nominativ","Plural"]},{"form":"Lyrikbandes","tags":["Genitiv","Singular"]},{"form":"Lyrikbänden","tags":["Dativ","Plural"]}],"senses":[{"definition":"gebundenes Buch, das Lyrik enthält"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Lyrik und Band"],"examples":[{"text":"„Mit dem teuren Fernseher im Wohnzimmer, der teuren Stereoanlage und den aus Backsteinen und Brettern selbstgebauten Bücherregalen voller Lyrikbände hatte er nicht gerechnet, vor allem nicht mit Coleridge, Blake und Byron.“","reference":"Don Winslow: London Undercover. Suhrkamp, Berlin 2015, ISBN 978-3-518-46580-6, Seite 184 ."},{"text":"„Die Lyrikbände, die ich behalten möchte, stelle ich in das Regal neben dem Bett.“","reference":"Auđur Ava Ólafsdóttir: Eden. Roman. 3. Auflage. Insel, Berlin 2026 (übersetzt von Tina Flecken), ISBN 978-3-458-64543-6, Seite 123. 1. Auflage 2025; Isländisches Original Reykjavík 2022."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lyrikband","id":"5617ed49ac3a41"},"006c-0079:5f0baa0221bcbc":{"word":"Lyssavirus","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Lys·sa·vi·rus","de-DE":"Lys·sa·vi·rus"},"forms":[{"form":"Lyssaviren","tags":["Nominativ","Plural"]},{"form":"Lyssavirus","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Virus aus der Familie Rhabdoviridae"}],"synonyms":[],"origins":[],"examples":[{"text":"„So wie die Ächtung von Schweinefleisch und von Schalentieren im Alten Testament vielen Menschen der Antike einen elenden Tod durch Vergiftung mit Trichinen oder Salmonellen ersparte, hielt die abergläubische Furcht vor Wölfen sie davon ab, mit Speichel in Berührung zu kommen, der mit großer Wahrscheinlichkeit Träger des Lyssavirus war, einer Gattung morphologisch ähnlicher Einzelstrang-RNS-Viren, die weltweit in Wirtstieren nachgewiesen werden können.“","reference":"Chuck Palahniuk: Das Kainsmal. Goldmann, München 2007, ISBN 978-3-442-54632-9, Seite 75 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lyssavirus","id":"5f0baa0221bcbc"},"006c-0079:a256c376c7b511":{"word":"Lymphknotenkrebs","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Lymph·kno·ten·krebs","de-DE":"Lymph·kno·ten·krebs"},"forms":[{"form":"Lymphknotenkrebs","tags":["Nominativ","Singular"]},{"form":"Lymphknotenkrebse","tags":["Nominativ","Plural"]},{"form":"Lymphknotenkrebsen","tags":["Dativ","Plural"]},{"form":"Lymphknotenkrebses","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Krebserkrankung der Lymphknoten"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Lymphknoten und Krebs"],"examples":[{"text":"„Als bei Gabriel José García Márquez Lymphknotenkrebs diagnostiziert wurde, verriet er den Grund, warum er sein ganzes Leben lang wie ein Schlot geraucht hatte: Er hatte es nie für möglich gehalten, als systemkritischer Intellektueller und Journalist im fast anarchistischen Kolumbien so lange am Leben zu bleiben.“","reference":"Kim Young-ha: Im Reich der Lichter. Heyne, München 2008, ISBN 978-3-453-40544-8, Seite 315 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lymphknotenkrebs","id":"a256c376c7b511"},"006c-0079:786cce219a5af7":{"word":"Lynbrook","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Lyn·brook","de-DE":"Lyn·brook"},"forms":[{"form":"Lynbrooks","tags":["Genitiv","Singular"]},{"form":"des Lynbrook","tags":["Genitiv","Singular"]},{"form":"des Lynbrooks","tags":["Genitiv","Singular"]},{"form":"(das) Lynbrook","tags":["Nominativ","Singular"]},{"form":"(dem) Lynbrook","tags":["Dativ","Singular"]}],"senses":[{"definition":"Ort im US-Bundesstaat New York"}],"synonyms":[],"origins":[],"examples":[{"text":"„Ihre Eltern waren verständlicherweise skeptisch gegenüber diesem stürmischen jungen Mann, der sich den Sommer über als Aushilfsarbeiter - gelegentlich auch als Müllmann - bei der Stadtverwaltung von Lynbrook, Long Island, sein Geld verdiente.“","reference":"John Douglas/Mark Olshaker: Reise in die Finsternis. Riva, München 2023, ISBN 978-3-7423-2446-7, Seite 203 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lynbrook","id":"786cce219a5af7"},"006c-0079:e551d30f75f6cf":{"word":"Lydenburg","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Ly·den·burg","de-DE":"Ly·den·burg"},"forms":[{"form":"Lydenburgs","tags":["Genitiv","Singular"]},{"form":"des Lydenburg","tags":["Genitiv","Singular"]},{"form":"des Lydenburgs","tags":["Genitiv","Singular"]},{"form":"(das) Lydenburg","tags":["Nominativ","Singular"]},{"form":"(dem) Lydenburg","tags":["Dativ","Singular"]}],"senses":[{"definition":"Stadt in der südafrikanischen Provinz Mpumalanga"}],"synonyms":[],"origins":[],"examples":[{"text":"„Er wollte sich nach Norden in das bergige Hochland hinter Lydenburg durchschlagen, um dort seine Truppen für den Guerillakrieg neu zu formieren; als Sammelpunkt hatte er Hectorspruit ausgewählt, die vorletzte Bahnstation vor der Grenze zu Mosambik.“","reference":"Martin Bossenbroek: Tod am Kap. Geschichte des Burenkriegs. C.H.Beck, München 2016, ISBN 978-3-406-68812-6, Seite 413 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lydenburg","id":"e551d30f75f6cf"},"006c-0079:edef86f7fd83b6":{"word":"Lyriden","partOfSpeech":"Substantiv","gender":"","hyphenation":{"de-CH":"Ly·ri·den","de-DE":"Ly·ri·den"},"forms":[{"form":"Lyriden","tags":["Nominativ","Plural"]}],"senses":[{"definition":"jährlich im April zu beobachtender Meteorschauer, dessen scheinbarer Ursprung (Radiant) im Sternbild Leier (Lyra) liegt"}],"synonyms":[],"origins":[],"examples":[{"text":"„Bei den Lyriden handelt es sich um winzige Teilchen des Kometen ‚Thatcher C/1861 G1‘, dessen Umlaufbahn die Erde alljährlich kreuzt.“","reference":"Sternschnuppen der Lyriden blitzen am Nachthimmel. In: Norddeutscher Rundfunk. 22. April 2025 (URL, abgerufen am 5. Januar 2026) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lyriden","id":"edef86f7fd83b6"},"006c-0079:2a3c4875fdc8c9":{"word":"Lykabettus","partOfSpeech":"Toponym","gender":"der","hyphenation":{"de-CH":"Ly·ka·bet·tus","de-DE":"Ly·ka·bet·tus"},"forms":[{"form":"Lykabettus","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Berg in Athen"}],"synonyms":[],"origins":[],"examples":[{"text":"„Seine Augen richteten sich auf einen leicht bewaldeten Berghang, der hinter den Häuserreihen sichtbar war. Es war der Lykabettus, ein 300 Meter hoher Berg, der einen Ausblick über die Stadt bot.“","reference":"Dalton Fury: Eine tödliche Einheit. Festa, Leipzig 2021, ISBN 978-3-86552-901-5, Seite 29 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lykabettus","id":"2a3c4875fdc8c9"},"006c-0079:bb371495f1220c":{"word":"Lynwood","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Lyn·wood","de-DE":"Lyn·wood"},"forms":[{"form":"Lynwoods","tags":["Genitiv","Singular"]},{"form":"des Lynwood","tags":["Genitiv","Singular"]},{"form":"des Lynwoods","tags":["Genitiv","Singular"]},{"form":"(das) Lynwood","tags":["Nominativ","Singular"]},{"form":"(dem) Lynwood","tags":["Dativ","Singular"]}],"senses":[{"definition":"Stadt im US-Bundesstaat Kalifornien"}],"synonyms":[],"origins":[],"examples":[{"text":"„Sache ist ferner: Wie wir gehört haben, ist auch ein Gelände mit umgebauten Pferdeställen in Betracht gezogen worden, in denen während des Zweiten Weltkriegs einmal Japaner interniert waren, außerdem ein umgebautes Bungalow-Motel in Lynwood, komplett mit herzförmigen Betten und schäbigen goldumrandeten Spiegeln.“","reference":"James Ellroy: White Jazz. Ullstein, Berlin 2001, ISBN 978-3-548-25001-4, Seite 125 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Lynwood","id":"bb371495f1220c"}};
